#!/usr/bin/env python3
"""Generate append equivalence cases from the existing pinned batch cases."""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parent.parent
PATTERN = re.compile(
    r'func example(\d+)\(\): Unit \{.*?'
    r'\.profile\(MarkdownProfile\.(\w+)\(\)\).*?'
    r'\.parse\(\s*("(?:\\.|[^"\\])*")\s*\)', re.S
)


def generate() -> str:
    output = [
        'package markdown\n',
        'import std.unittest.*\nimport std.unittest.testmacro.*\n',
        '// Generated by scripts/generate_append_spec_tests.py from pinned batch cases.\n',
        '@Test\nclass AppendStandardCorpusTests {\n',
    ]
    for source, count, label in [
        ('generated_commonmark_spec_test.cj', 652, 'commonMark0312'),
        ('generated_gfm_spec_test.cj', 671, 'gfm029'),
    ]:
        cases = PATTERN.findall((ROOT / 'src' / source).read_text())
        assert len(cases) == count, (source, len(cases), count)
        numbers = [int(n) for n, _, _ in cases]
        assert numbers == sorted(set(numbers))
        missing = set(range(1, max(numbers) + 1)) - set(numbers)
        assert missing == ({279, 280} if label == 'gfm029' else set())
        output.append(f'    @TestCase\n    func {label}AppendEquivalence(): Unit {{\n')
        output.append('        let cases: Array<(MarkdownProfile, String)> = [\n')
        output.append(',\n'.join(f'            (MarkdownProfile.{profile}(), {literal})'
                                  for _, profile, literal in cases))
        output.append('\n        ]\n        verifyAppendStandardCases(cases)\n    }\n')
    output.append('}\n')
    return ''.join(output)


if __name__ == '__main__':
    (ROOT / 'src' / 'generated_append_spec_test.cj').write_text(generate())
